script='assert(loadfile("C:/Users/Administrator/Desktop/Ninja Ascension/jogo/01_conteudo_apk/assets/src/cocos/cocos2d/json.lua"))()\n\nlocal widgets={}\nlocal function label() return {text=\'\',children=0,setString=function(self,s)self.text=s end} end\nwidgets.Label_1p_name=label();widgets.Label_2p_name=label()\ncc={nrSpineCommand=function()end}\nccui={Helper={seekWidgetByName=function(_,_,name)return assert(widgets[name])end},RichText={create=function()error(\'PC Arena cleared the visible label for RichText\')end}}\n_enum_fight_type={_fight_type_11=11,_fight_type_218=218,_fight_type_220=220}\n_ED={battleData={battle_init_type=11,defender_name=\'ItachiBR\'}}\nFightUI={}\nfunction FightUI:updateDrawPlayerInfo( info )\n    local attackerSpeedValue = info[5]\n    local defnederSpeedValue = info[6]\n    local root = self.roots[1]\n    local Label_1p_name = ccui.Helper:seekWidgetByName(root,"Label_1p_name")\n    Label_1p_name:setString(info[1] or "")\n    local Label_2p_name = ccui.Helper:seekWidgetByName(root,"Label_2p_name")\n    --TODO: wf 2140 【战斗】【战斗回放】在PVP战斗回放中，如果玩家是纯数字名字，名字就会出现显示错误\n--    if __lua_project_id == __lua_project_l_digital or __lua_project_id == __lua_project_l_dragonball or __lua_project_id == __lua_project_l_dragonball2 or __lua_project_id == __lua_project_l_pokemon or __lua_project_id == __lua_project_onepiece or __lua_project_id == __lua_project_l_naruto then\n--        if info[2] ~= nil and info[2] ~= "" then\n--            if tonumber(info[2]) ~= nil then\n--                local word_info = dms.element(dms["word_mould"], tonumber(info[2]))\n--                if word_info ~= nil then\n--                    info[2] = word_info[3]\n--                end\n--            end\n--        end\n--    end\n    local defenderName = info[2]\n    local nativeArena = type(cc.nrSpineCommand)==\'function\' and\n        (_ED.battleData.battle_init_type == _enum_fight_type._fight_type_11 or _ED.nr_arena_fight_rank ~= nil)\n    if nativeArena then\n        local savedName = _ED.nr_arena_fight_rank and _ED.nr_arena_defender_name or _ED.battleData.defender_name\n        if savedName ~= nil and savedName ~= \'\' then defenderName = savedName end\n    end\n    -- 世界boss\n    if _ED.battleData.battle_init_type == _enum_fight_type._fight_type_218 then\n        local word_info = dms.element(dms["word_mould"], zstring.tonumber(defenderName))\n        defenderName = word_info[3]\n    end\n    Label_2p_name:setString(defenderName or "")\n    if _ED.battleData.battle_init_type == _enum_fight_type._fight_type_220 then\n        Label_1p_name:setString(_ED.battleData.attacker_name)\n        Label_2p_name:setString(_ED.battleData.defender_name)\n    end\n    if _ED.battleData.battle_init_type == _enum_fight_type._fight_type_11 and not nativeArena then\n        local _richText2 = ccui.RichText:create()\n        -- if Label_2p_name:getContentSize().width > 0 then\n            _richText2:ignoreContentAdaptWithSize(false)\n            _richText2:setContentSize(cc.size(500, 0))\n            _richText2:setAnchorPoint(cc.p(0, 0))\n            char_str = info[2]\n            local rt, count, text = draw.richTextCollectionMethod(_richText2, \n            char_str, \n            cc.c3b(255, 255, 255),\n            cc.c3b(255, 255, 255),\n            0, \n            0, \n            "", \n            Label_2p_name:getFontSize(),\n            chat_rich_text_color)\n            _richText2:formatTextExt()\n            local rsize = _richText2:getContentSize()\n            _richText2:setPositionY(Label_2p_name:getContentSize().height/2)\n            _richText2:setPositionX(-88 - (rsize.width)/2)\n            Label_2p_name:addChild(_richText2)\n            Label_2p_name:setString("")\n        -- end\n    end\n\n\n\nend\n\nlocal function check(name,info)\n FightUI.updateDrawPlayerInfo({roots={{}}},info or {\'RenegadoBR\',\'\',0,0,84514,930})\n assert(widgets.Label_2p_name.text==name,\'Enemy name disappeared: \'..widgets.Label_2p_name.text)\n assert(widgets.Label_1p_name.text==\'RenegadoBR\')\nend\ncheck(\'ItachiBR\') -- historical battle with no live flags\n_ED.nr_arena_fight_rank=2;_ED.nr_arena_defender_name=\'Aeglos\'\ncheck(\'Aeglos\') -- live opponent changes, not previous replay\'s defender\n_ED.nr_arena_fight_rank=nil;_ED.battleData.defender_name=\'12345\'\ncheck(\'12345\') -- numeric names remain player names\n_ED.battleData.battle_init_type=0\ncheck(\'NPC\',{\'RenegadoBR\',\'NPC\',0,0,1,2}) -- PvE unchanged\nlocal access=assert(loadfile("C:/Users/Administrator/Desktop/Ninja Ascension/jogo/port/lua/fight_test_access.lua"))()\nassert(access.enabled(81) and access.enabled(196) and not access.enabled(80) and not access.enabled(1))\ncc.nrSpineCommand=nil;assert(not access.enabled(81))\nprint(\'ARENA_ENEMY_NAME_PASSED live, replay, numeric, PvE; PC test access scoped\')\n'
